%[text] # View signals - Reducer input torques
torque_unit = "N*m";
x_upper_bound = 80;
%[text] Motor
% Populate the MotorTorqueInput table data in the base workspace.
loadLUTData_Reducer_Motor_FlipTorque

fig = bevutil1.SignalUtil.plotLookupTable1D( ... %[output:5a36f18f]
  MotorTorqueInput.Time.value("s"), ... %[output:5a36f18f]
  MotorTorqueInput.Torque.value(torque_unit), ... %[output:5a36f18f]
  InterpolationInterval = 0.1, ... %[output:5a36f18f]
  PlotXUpperBound = x_upper_bound, ... %[output:5a36f18f]
  Title="Motor torque input", XLabel="Time (s)", YLabel=("(" + torque_unit + ")") ); %[output:5a36f18f]

fig.Position(3:4) = [800 300];  % width height %[output:5a36f18f]
%[text] Axle
% Populate the AxleTorqueInput table data in the base workspace.
loadLUTData_Reducer_Axle_FlipTorque

fig = bevutil1.SignalUtil.plotLookupTable1D( ... %[output:30472e7b]
  AxleTorqueInput.Time.value("s"), ... %[output:30472e7b]
  AxleTorqueInput.Torque.value(torque_unit), ... %[output:30472e7b]
  InterpolationInterval = 0.1, ... %[output:30472e7b]
  PlotXUpperBound = x_upper_bound, ... %[output:30472e7b]
  Title="Axle torque input", XLabel="Time (s)", YLabel=("(" + torque_unit + ")") ); %[output:30472e7b]

fig.Position(3:4) = [800 300];  % width height %[output:30472e7b]
